add('drsample','Target Behavior Reward Model','Estimate','[p[3]+p[0]/p[1]*(p[2]-p[3])]',lambda p:[p[3]+p[0]/p[1]*(p[2]-p[3])],'A single-action toy has Target {Target}, Behavior {Behavior}, Reward {Reward}, outcome Model {Model}. What model-plus-weighted-residual estimate results?','This one-action augmentation exposes the residual correction. Double robustness requires the full target action average and identification assumptions.','p[0]<0||p[0]>1||p[1]<=0||p[1]>1')
