# Simpson quadrature is independent of the Python erf reference used by fixtures.
_cdf='''(z:number)=>{if(z<=-10)return 0;if(z>=10)return 1;const n=2048,h=z/n;let s=1+Math.exp(-z*z/2);for(let i=1;i<n;i++)s+=(i%2?4:2)*Math.exp(-Math.pow(i*h,2)/2);return .5+h*s/(3*Math.sqrt(2*Math.PI));}'''
def bs(p):
 s,k,r,v,t=p
 if t==0:return [max(s-k,0)]
 if v==0:return [max(s-k*math.exp(-r*t),0)]
 d=(math.log(s/k)+(r+v*v/2)*t)/(v*math.sqrt(t));cdf=lambda z:(1+math.erf(z/math.sqrt(2)))/2
 return [s*cdf(d)-k*math.exp(-r*t)*cdf(d-v*math.sqrt(t))]
add('blackscholes','Spot Strike Rate Sigma Time','Call','[(()=>{if(p[4]===0)return Math.max(p[0]-p[1],0);if(p[3]===0)return Math.max(p[0]-p[1]*Math.exp(-p[2]*p[4]),0);const cdf='+_cdf+',d=(Math.log(p[0]/p[1])+(p[2]+p[3]*p[3]/2)*p[4])/(p[3]*Math.sqrt(p[4]));return p[0]*cdf(d)-p[1]*Math.exp(-p[2]*p[4])*cdf(d-p[3]*Math.sqrt(p[4]));})()]',bs,'A toy European call has Spot {Spot}, Strike {Strike}, rate {Rate}, volatility Sigma {Sigma}, Time {Time}. Under the no-dividend constant-volatility Black-Scholes model, what price results?','The model averages discounted risk-neutral payoffs under specific market assumptions. Its value is not a recommendation or a market quote.','p[0]<=0||p[1]<=0||p[3]<0||p[4]<0')
